INSERT INTO `sys_dict` VALUES (2075, '应用名', 'overviewApp', '1', 'aim', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'AIM (originally AOL Instant Messenger) is an instant messaging application The protocol name is OSCAR (Open System for CommunicAtion in Realtime) and is used in both ICQ and AIM services');
INSERT INTO `sys_dict` VALUES (2076, '应用名', 'overviewApp', '1', 'amqp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'AMQP (Advanced Message Queuing Protocol) is an open standard application layer protocol for message-oriented middleware originated in 2003 by JP Morgan Chase in London');
INSERT INTO `sys_dict` VALUES (2077, '应用名', 'overviewApp', '1', 'arp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The ARP protocol is used to determine the MAC Address of a PC for which the IP address is known');
INSERT INTO `sys_dict` VALUES (2078, '应用名', 'overviewApp', '1', 'bgp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Border Gateway Protocol (BGP) is an inter Autonomous Systems routing protocol used by most ISPs');
INSERT INTO `sys_dict` VALUES (2079, '应用名', 'overviewApp', '1', 'bittorrent', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'BitTorrent is a peer-to-peer protocol for file sharing');
INSERT INTO `sys_dict` VALUES (2080, '应用名', 'overviewApp', '1', 'bxml', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The WAP Binary XML protocol defines an encoding scheme for the binary data used in WAP environments');
INSERT INTO `sys_dict` VALUES (2081, '应用名', 'overviewApp', '1', 'cotp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'COTP (Connection Oriented Transport Protocol) is a protocol ensuring the transport service in the OSI model');
INSERT INTO `sys_dict` VALUES (2082, '应用名', 'overviewApp', '1', 'cups', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Common Unix Printer System (CUPS) protocol is a cross-platform printing solution for UNIX environments It is based on the \\Internet Printing Protocol\\ and it is compatible with Microsoft operating systems since Windows 2000');
INSERT INTO `sys_dict` VALUES (2083, '应用名', 'overviewApp', '1', 'dailymotion', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Dailymotion is a website where users can send or watch videos');
INSERT INTO `sys_dict` VALUES (2084, '应用名', 'overviewApp', '1', 'dcerpc', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The DCERPC protocol is an RPC implementation used in Distributed Computing Environments This protocol is used by many software applications including Microsft Exchange');
INSERT INTO `sys_dict` VALUES (2085, '应用名', 'overviewApp', '1', 'dhcp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The DHCP protocol is used to configure automatically the network parameters of a station');
INSERT INTO `sys_dict` VALUES (2086, '应用名', 'overviewApp', '1', 'dict', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The DICT protocol is a TCP transaction based query/response protocol that enables a client to access dictionary definitions from a set of natural language dictionary databases');
INSERT INTO `sys_dict` VALUES (2087, '应用名', 'overviewApp', '1', 'directconnect', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'DirectConnect is a peer-to-peer protocol');
INSERT INTO `sys_dict` VALUES (2088, '应用名', 'overviewApp', '1', 'dns', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The DNS protocol is used to translate internet names (wwwsitecom) into IP address and vice versa This protocol plug-in classifies DNS and its \'children\' LLMNR mDNS and DNSSEC (RFC 4033 RFC 3225) which are recognizable by the value of the Q_DNS_NAME_RESOLUTION_TYPE attribute');
INSERT INTO `sys_dict` VALUES (2089, '应用名', 'overviewApp', '1', 'ebay', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Ebay is a famous online auction and shopping website');
INSERT INTO `sys_dict` VALUES (2090, '应用名', 'overviewApp', '1', 'edonkey', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Edonkey is a peer-to-peer protocol Classification is not guaranteed when the protocol obfuscation feature is enable (feature appeared in eMule version 047b)');
INSERT INTO `sys_dict` VALUES (2091, '应用名', 'overviewApp', '1', 'epm', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'End Point Mapper is a protocol used by Exchange to determine the ports used by various services');
INSERT INTO `sys_dict` VALUES (2092, '应用名', 'overviewApp', '1', 'established', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Established protocol is a virtual protocol grouping all TCP connections already established before starting analyzing the traffic (no SYNC)');
INSERT INTO `sys_dict` VALUES (2093, '应用名', 'overviewApp', '1', 'ftp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The FTP protocol is used for reliable data transfer between a client and a server');
INSERT INTO `sys_dict` VALUES (2094, '应用名', 'overviewApp', '1', 'ftp_data', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'This protocol is used to transport data in data connection of FTP communication');
INSERT INTO `sys_dict` VALUES (2095, '应用名', 'overviewApp', '1', 'giop', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The General Inter-Orb protocol (GIOP) is used to make requests or return replies between ORBs in a Corba environment');
INSERT INTO `sys_dict` VALUES (2096, '应用名', 'overviewApp', '1', 'gmail', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Gmail is the Google webmail service This plugin also classifies Gmail image proxy server Google Inbox is now part of Gmail');
INSERT INTO `sys_dict` VALUES (2097, '应用名', 'overviewApp', '1', 'gnutella', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Gnutella is a peer-to-peer protocol');
INSERT INTO `sys_dict` VALUES (2098, '应用名', 'overviewApp', '1', 'goboogy', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'GoBoogy is a peer-to-peer (p2p) application used to share files with other GoBoogy users over the Internet');
INSERT INTO `sys_dict` VALUES (2099, '应用名', 'overviewApp', '1', 'google', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'This protocol is used for sending user queries to the Google search engine This signature only classifies non-encrypted queries to the Google servers');
INSERT INTO `sys_dict` VALUES (2100, '应用名', 'overviewApp', '1', 'google_earth', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Google Earth is a program used to view a virtual Earth in 3D Part of the traffic generated on Windows and Mac is classified as google_maps');
INSERT INTO `sys_dict` VALUES (2101, '应用名', 'overviewApp', '1', 'google_groups', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Google Groups allows the user to create and post in forums and email-based groups');
INSERT INTO `sys_dict` VALUES (2102, '应用名', 'overviewApp', '1', 'google_maps', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Google Maps can be used to calculate routes and to look at maps The encrypted traffic is classified as google This plug-in also classifies the traffic destined to the Google Location service or third-party applications using its API to locate a device');
INSERT INTO `sys_dict` VALUES (2103, '应用名', 'overviewApp', '1', 'gtp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The GPRS Tunneling Protocol (GTP) is used to create a tunnel between the SGSN and GGSNs of a mobile operator network thus allowing mobile station data to be transmitted');
INSERT INTO `sys_dict` VALUES (2104, '应用名', 'overviewApp', '1', 'h225', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The H225 Protocol is a VoIP protocol used for call signaling and RAS (Registration Admission and Status)');
INSERT INTO `sys_dict` VALUES (2105, '应用名', 'overviewApp', '1', 'h245', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'H245 is a VoIP protocol used for call signaling codec negotiation');
INSERT INTO `sys_dict` VALUES (2106, '应用名', 'overviewApp', '1', 'hsrp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Cisco Hot Standby Router Protocol (HSRP) enables you to manage router redundancy in a network');
INSERT INTO `sys_dict` VALUES (2107, '应用名', 'overviewApp', '1', 'http', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Hypertext Transfer Protocol (HTTP) is used for browsing the web');
INSERT INTO `sys_dict` VALUES (2108, '应用名', 'overviewApp', '1', 'https', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'HTTPS is the secure version of HTTP');
INSERT INTO `sys_dict` VALUES (2109, '应用名', 'overviewApp', '1', 'ica', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'ICA (Independent Computing Architecture) is a communication protocol and a property of the Citrix Company');
INSERT INTO `sys_dict` VALUES (2110, '应用名', 'overviewApp', '1', 'ident', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Identification Protocol provides a means to determine the identity of a user of a specific TCP connection');
INSERT INTO `sys_dict` VALUES (2111, '应用名', 'overviewApp', '1', 'imap', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The IMAP protocol (Internet Message Access Protocol Version 4) enables a client to access and manipulate electronic mail messages on a server');
INSERT INTO `sys_dict` VALUES (2112, '应用名', 'overviewApp', '1', 'imaps', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'IMAPS is the secure version of the IMAP protocol');
INSERT INTO `sys_dict` VALUES (2113, '应用名', 'overviewApp', '1', 'imp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'IMP is the IMAP webmail of the Horde project');
INSERT INTO `sys_dict` VALUES (2114, '应用名', 'overviewApp', '1', 'ipp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Internet Printing Protocol (IPP) is a standard used for remote printing using Internet tools and technologies');
INSERT INTO `sys_dict` VALUES (2115, '应用名', 'overviewApp', '1', 'irc', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'IRC (Internet Relay Chat) is an instant messaging protocol');
INSERT INTO `sys_dict` VALUES (2116, '应用名', 'overviewApp', '1', 'ircs', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'IRCs is the secure version of the IRC protocol');
INSERT INTO `sys_dict` VALUES (2117, '应用名', 'overviewApp', '1', 'isakmp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Internet Security Association and Key Management Protocol (ISAKMP) defines procedures and packet formats to establish negotiate modify and delete Security Associations (SA)');
INSERT INTO `sys_dict` VALUES (2118, '应用名', 'overviewApp', '1', 'jabber', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Jabber is an open standard instant messaging and presence system involving the XMPP protocol');
INSERT INTO `sys_dict` VALUES (2119, '应用名', 'overviewApp', '1', 'jetdirect', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Jetdirect protocol is used by HP network printers');
INSERT INTO `sys_dict` VALUES (2120, '应用名', 'overviewApp', '1', 'kazaa', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'KaZaA is a peer-to-peer protocol');
INSERT INTO `sys_dict` VALUES (2121, '应用名', 'overviewApp', '1', 'krb5', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Kerberos provides a means to verify the identities of the different workstations on an open (unprotected) network');
INSERT INTO `sys_dict` VALUES (2122, '应用名', 'overviewApp', '1', 'l2tp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Layer Two Tunneling Protocol (L2TP) is an extension of the Point-to-Point Tunneling Protocol (PPTP) used by an Internet service provider (ISP) to enable the operation of a virtual private network (VPN) over the Internet');
INSERT INTO `sys_dict` VALUES (2123, '应用名', 'overviewApp', '1', 'ldap', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'LDAP (Lightweight Directory Access Protocol) is a protocol used for accessing directory services Windows environments use this protocol to send queries to Active Directory');
INSERT INTO `sys_dict` VALUES (2124, '应用名', 'overviewApp', '1', 'ldaps', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Secure LDAP is the Secure version of the LDAP protocol');
INSERT INTO `sys_dict` VALUES (2125, '应用名', 'overviewApp', '1', 'lotusnotes', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Lotus Notes is a groupware knowledge management system which integrates various services such as web browsing calendaring and mailing');
INSERT INTO `sys_dict` VALUES (2126, '应用名', 'overviewApp', '1', 'lpr', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'LPR is a protocol providing printing services and used in Berkeley distributions of the Unix operating system');
INSERT INTO `sys_dict` VALUES (2127, '应用名', 'overviewApp', '1', 'mapi', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'MS Exchange Message API is a protocol used by Exchange clients to retrieve their emails');
INSERT INTO `sys_dict` VALUES (2128, '应用名', 'overviewApp', '1', 'mcafee', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'McAfee is one of the leaders in intrusion prevention and security risk management on the web');
INSERT INTO `sys_dict` VALUES (2129, '应用名', 'overviewApp', '1', 'mcs', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Multipoint Communication Service (MCS) is a multipoint data delivery service for use in multimedia and audiovisual conferencing service It provides the mechanism for multipoint aware applications to send data to all or a subset of the group with a single send primitive and to force if desired a uniformly sequenced reception of data for all users');
INSERT INTO `sys_dict` VALUES (2130, '应用名', 'overviewApp', '1', 'mgcp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'MGCP protocol is used as signaling protocol for voice IP applications');
INSERT INTO `sys_dict` VALUES (2131, '应用名', 'overviewApp', '1', 'mms', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'MMS protocol is used extensively nowadays by Microsoft video streaming servers It enables to stream a file in real time to many simultaneous viewers');
INSERT INTO `sys_dict` VALUES (2132, '应用名', 'overviewApp', '1', 'mmse', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The MultiMedia Messages Encapsulation protocol (MMSE) is used by mobile stations to send multimedia messages');
INSERT INTO `sys_dict` VALUES (2133, '应用名', 'overviewApp', '1', 'mount', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Mount protocol is related to the NFS protocol It provides operating system specific services to launch the NFS protocol -- looking up server path names validating user identity and checking access permissions');
INSERT INTO `sys_dict` VALUES (2134, '应用名', 'overviewApp', '1', 'mute', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'MUTE File Sharing is a peer-to-peer network that provides easy search-and-download functionality');
INSERT INTO `sys_dict` VALUES (2135, '应用名', 'overviewApp', '1', 'myspace', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'MySpace is one of most popular social networking sites on the Web The myspace RTMP traffic is not classifiable');
INSERT INTO `sys_dict` VALUES (2136, '应用名', 'overviewApp', '1', 'mysql', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'MySQL is an open source relational database management system (RDBMS) that uses Structured Query Language (SQL) the most popular language for adding accessing and processing data in a database');
INSERT INTO `sys_dict` VALUES (2137, '应用名', 'overviewApp', '1', 'nbns', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'NetBios Name Service (NBNS) is a protocol resulting from NetBios and which makes it possible to manage the names in a Microsoft NetBios network NetBios names are human readable and NBNS serves the same purpose as the DNS system in IP environments');
INSERT INTO `sys_dict` VALUES (2138, '应用名', 'overviewApp', '1', 'netbios', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'NetBIOS defines a software interface and standard methods providing a communication interface between the application program and the attached medium NetBIOS is used in various LAN (Ethernet Token Ring etc) as well as WAN environments such TCP/IP PPP and X25 networks');
INSERT INTO `sys_dict` VALUES (2139, '应用名', 'overviewApp', '1', 'netflow', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'NetFlow is a Cisco protocol that provides nearly real-time traffic monitoring aggregation and statistic evaluation multicriteria data flow selection using source/destination IP addresses protocols etc');
INSERT INTO `sys_dict` VALUES (2140, '应用名', 'overviewApp', '1', 'nfs', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The NFS protocol provides transparent remote access to shared file systems across networks as described in RFC 1813');
INSERT INTO `sys_dict` VALUES (2141, '应用名', 'overviewApp', '1', 'nlockmgr', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The network lock manager is a facility that works in cooperation with the Network File System (NFS) to provide a System V style of advisory file and record locking over the network');
INSERT INTO `sys_dict` VALUES (2142, '应用名', 'overviewApp', '1', 'nntp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Network News Transport Protocol (NNTP) is used for the distribution inquiry retrieval and posting of net news articles using a reliable stream-based mechanism');
INSERT INTO `sys_dict` VALUES (2143, '应用名', 'overviewApp', '1', 'nntps', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Secure version of the NNTP protocol');
INSERT INTO `sys_dict` VALUES (2144, '应用名', 'overviewApp', '1', 'nspi', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Name Service Provider Interface is a protocol used by Exchange');
INSERT INTO `sys_dict` VALUES (2145, '应用名', 'overviewApp', '1', 'ntp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Network Time Protocol (NTP) is a time synchronization system for computer clocks through the Internet network It provides mechanisms to synchronize time and coordinate time distribution in a large network');
INSERT INTO `sys_dict` VALUES (2146, '应用名', 'overviewApp', '1', 'openft', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'OpenFT is a peer-to-peer protocol');
INSERT INTO `sys_dict` VALUES (2147, '应用名', 'overviewApp', '1', 'owa', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Outlook Web App is used to access e-mail (including support for S/MIME) calendars contacts tasks documents (used with SharePoint or in 2010 Office Web Apps) and other mailbox content when access to the Microsoft Outlook desktop application is unavailable');
INSERT INTO `sys_dict` VALUES (2148, '应用名', 'overviewApp', '1', 'paltalk', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Paltalk is an instant messaging protocol');
INSERT INTO `sys_dict` VALUES (2149, '应用名', 'overviewApp', '1', 'paltalk_audio', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Proprietary protocol used by Paltalk in audio chats');
INSERT INTO `sys_dict` VALUES (2150, '应用名', 'overviewApp', '1', 'pop3', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Post Office Protocol - Version 3 (POP3) allows a workstation to simply and dynamically access a mail stored on a mail server');
INSERT INTO `sys_dict` VALUES (2151, '应用名', 'overviewApp', '1', 'pop3s', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Secure version of the POP3 protocol');
INSERT INTO `sys_dict` VALUES (2152, '应用名', 'overviewApp', '1', 'portmap', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Port Mapper protocol maps RPC program and version numbers to port numbers This program makes dynamic binding of remote programs possible');
INSERT INTO `sys_dict` VALUES (2153, '应用名', 'overviewApp', '1', 'postgres', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'PostgreSQL is a sophisticated Object-Relational DBMS supporting almost all SQL constructs including subselects transactions and user-defined types and functions');
INSERT INTO `sys_dict` VALUES (2154, '应用名', 'overviewApp', '1', 'pptp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Point-to-Point Tunneling Protocol allows the Point to Point Protocol (PPP) to be tunnelled through an IP network');
INSERT INTO `sys_dict` VALUES (2155, '应用名', 'overviewApp', '1', 'q931', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Q931 protocol enables the use of voice and image on networks for video conferencing It provides no flow control however or retransmission since the underlying layers are assumed to be reliable and the circuit-oriented nature of ISDN allocates bandwidth in fixed increments of 64 kbps Q931 does manage connection setup and close Like TCP Q931 documents both the protocol itself and a state machine');
INSERT INTO `sys_dict` VALUES (2156, '应用名', 'overviewApp', '1', 'qq', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'QQ is the most popular free instant messaging computer program in China');
INSERT INTO `sys_dict` VALUES (2157, '应用名', 'overviewApp', '1', 'quake', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Quake is a protocol allowing communication between Quake Clients and Quake servers');
INSERT INTO `sys_dict` VALUES (2158, '应用名', 'overviewApp', '1', 'radius', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'RADIUS (Remote Authentication Dial-In User Service) is a client/server protocol that enables remote access servers to communicate with a central server to authenticate dial-in users and authorize their access to the requested system or service');
INSERT INTO `sys_dict` VALUES (2159, '应用名', 'overviewApp', '1', 'rdp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'A key component of Terminal Server is the Remote Desktop Protocol which allows a thin client to communicate with the Terminal Server over the network This protocol is based on International Telecommunications Union\'s (ITU) T120 protocol an international standard multichannel conferencing protocol currently used in the Microsoft NetMeeting conferencing software product It is tuned for high-bandwidth enterprise environments and will also support encrypted sessions');
INSERT INTO `sys_dict` VALUES (2160, '应用名', 'overviewApp', '1', 'rdt', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'This protocol is used to transport audio/video data');
INSERT INTO `sys_dict` VALUES (2161, '应用名', 'overviewApp', '1', 'rfb', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'RFB (Remote Frame Buffer) is a simple protocol for remote access to graphical user interfaces');
INSERT INTO `sys_dict` VALUES (2162, '应用名', 'overviewApp', '1', 'rip1', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'RIP1 (Routing Information Protocol Version 1) is a Distance Vector routing protocol used in Inter Autonomous Systems');
INSERT INTO `sys_dict` VALUES (2163, '应用名', 'overviewApp', '1', 'rip2', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'RIP2 (Routing Information Protocol Version 2) is an enhancement of the Version 1 of the protocol The main differences are the use of multicast instead of broadcast and the support of variable length subnet mask networks since subnets are now sent inside the updates');
INSERT INTO `sys_dict` VALUES (2164, '应用名', 'overviewApp', '1', 'ripng1', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'RIPng (RIP New Generation) is intended to allow routers to exchange information for computing routes through an IPv6-based network RIPng is a distance vector protocol RIPng should be implemented only in routers since IPv6 provides other mechanisms for router discovery');
INSERT INTO `sys_dict` VALUES (2165, '应用名', 'overviewApp', '1', 'rlogin', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Rlogin protocol is used to establish a bidirectional communication to distant terminals');
INSERT INTO `sys_dict` VALUES (2166, '应用名', 'overviewApp', '1', 'rlp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Resource Location Protocol (RLP) is a protocol used to discover the location of resources present in a network');
INSERT INTO `sys_dict` VALUES (2167, '应用名', 'overviewApp', '1', 'rpc', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'RPC (Remote Procedure Call) is an easy and popular paradigm for implementing the client-server model of distributed computing  A request is sent to a remote system to execute a designated procedure using arguments supplied and the result is returned to the caller');
INSERT INTO `sys_dict` VALUES (2168, '应用名', 'overviewApp', '1', 'rquota', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The RQuota protocol enables the implementation of quotas on remote machines It is used in conjunction with the NFS protocol');
INSERT INTO `sys_dict` VALUES (2169, '应用名', 'overviewApp', '1', 'rsh', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The RSH protocol allows a user to establish a secure connection to a remote host and to obtain a shell allowing commands to be sent to the remote machine to be executed');
INSERT INTO `sys_dict` VALUES (2170, '应用名', 'overviewApp', '1', 'rstat', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The RStat protocol is used in the Sun NFS family to exchange statistics on network activity');
INSERT INTO `sys_dict` VALUES (2171, '应用名', 'overviewApp', '1', 'rsync', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Rsync is a protocol used by various services performing updates It greatly speeds up the update process since only the differences between two sets of files are transfered instead of the whole new file');
INSERT INTO `sys_dict` VALUES (2172, '应用名', 'overviewApp', '1', 'rtcp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Real-time Transport Control Protocol (RTCP) allows monitoring of the data delivery in a manner scalable to large multicast networks and to provide minimal control and identification functionality This signature also classifies the encrypted profile of RTCP known as sRTCP');
INSERT INTO `sys_dict` VALUES (2173, '应用名', 'overviewApp', '1', 'rtp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'RTP is the real-time transport protocol used to transmit real-time data such as audio video or simulation data over multicast or unicast network services This signature also classifies the SRTP and ZRTP encrypted transport protocols');
INSERT INTO `sys_dict` VALUES (2174, '应用名', 'overviewApp', '1', 'rtsp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Real Time Streaming Protocol ((RTSP|RTSP)) is an application-level protocol for control over the delivery of data with real-time properties (RTSP|RTSP) provides an extensible framework to enable controlled on-demand delivery of real-time data such as audio and video');
INSERT INTO `sys_dict` VALUES (2175, '应用名', 'overviewApp', '1', 'rusers', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The RUser\'s protocol provides a service that lists users currently logged on a remote server');
INSERT INTO `sys_dict` VALUES (2176, '应用名', 'overviewApp', '1', 'sap', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'SAP is both a protocol and the name of an ERP application used by most companies');
INSERT INTO `sys_dict` VALUES (2177, '应用名', 'overviewApp', '1', 'sccp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Skinny Client Control Protocol (SCCP) is a Cisco proprietary protocol used between Cisco Call Manager and Cisco VOIP phones It is also supported by some other vendors');
INSERT INTO `sys_dict` VALUES (2178, '应用名', 'overviewApp', '1', 'shoutcast', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Shoutcast is a protocol used to stream audio files over HTTP This app classifies streaming from the web version of Shoutcast');
INSERT INTO `sys_dict` VALUES (2179, '应用名', 'overviewApp', '1', 'sip', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Session Initiation Protocol (SIP) is the Internet Engineering Task Force\'s (IETF\'s) standard for multimedia conferencing over IP Like other VoIP protocols SIP is designed to address the functions of signaling and session management within a packet telephony network');
INSERT INTO `sys_dict` VALUES (2180, '应用名', 'overviewApp', '1', 'skype', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Skype is a widely used voice over IP protocol It was merged with MSN service in 2013 It\'s required to use this protocol in conjunction with windowslive protocol to optimize the coverage of traffic generated by Skype clients This app plug-in now includes previous MSN-related flow signatures to provide both login and chat support UDP classification is assisted using DNS Caching');
INSERT INTO `sys_dict` VALUES (2181, '应用名', 'overviewApp', '1', 'slsk', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Soulseek is a peer-to-peer protocol');
INSERT INTO `sys_dict` VALUES (2182, '应用名', 'overviewApp', '1', 'smb', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Server Message Block protocol (SMB) provides a method for client applications to read and write to files and to request services from server programs in a computers network This protocol plug-in supports SMB/SMB2 protocols as well as SMB 30 when SMB Multichannel is not in use The SMB RDMA (Remote Direct Memory Access) implementation over the iWarp stack (incl SMB Direct) is supported');
INSERT INTO `sys_dict` VALUES (2183, '应用名', 'overviewApp', '1', 'smtp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Simple Mail Transfer Protocol (SMTP) is a protocol used to transfer emails reliably and efficiently');
INSERT INTO `sys_dict` VALUES (2184, '应用名', 'overviewApp', '1', 'smtps', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Secure version of the SMTP protocol');
INSERT INTO `sys_dict` VALUES (2185, '应用名', 'overviewApp', '1', 'snmp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'SNMP is a request/response protocol that communicates management information between two types of SNMP software entities: SNMP applications (also called SNMP managers) and SNMP agents');
INSERT INTO `sys_dict` VALUES (2186, '应用名', 'overviewApp', '1', 'soap', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'SOAP is a lightweight protocol based on XML intended for exchanging structured information in a decentralized distributed environment Note: this protocol can be found in HTTP requests but it won\'t be classified if some known web application or service was classified instead');
INSERT INTO `sys_dict` VALUES (2187, '应用名', 'overviewApp', '1', 'socks4', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Socks 4 is an authentication protocol');
INSERT INTO `sys_dict` VALUES (2188, '应用名', 'overviewApp', '1', 'socks5', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'SOCKS is an Internet protocol that exchanges network packets between a client and server through a proxy server The Socks5 protocol is defined in RFC 1928 offers more choices for authentication and adds support for IPv6 and UDP');
INSERT INTO `sys_dict` VALUES (2189, '应用名', 'overviewApp', '1', 'squirrelmail', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'SquirrelMail is a web-based email application written in the PHP scripting language');
INSERT INTO `sys_dict` VALUES (2190, '应用名', 'overviewApp', '1', 'srvloc', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Service Location Protocol is a decentralized lightweight scalable and extensible protocol for service discovery within a local area network');
INSERT INTO `sys_dict` VALUES (2191, '应用名', 'overviewApp', '1', 'ssdp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Simple Service Discovery Protocol (SSDP) provides a mechanism whereby network clients can discover desired network services');
INSERT INTO `sys_dict` VALUES (2192, '应用名', 'overviewApp', '1', 'ssh', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Secure Shell (SSH) sometimes known as Secure Socket Shell is a UNIX-based command interface and a protocol for obtaining secure access to a remote computer');
INSERT INTO `sys_dict` VALUES (2193, '应用名', 'overviewApp', '1', 'ssl', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Secure Sockets Layer (SSL) is a commonly-used protocol for managing the security of a message transmission on the Internet SSL has recently been succeeded by Transport Layer Security (TLS) which is based on SSL');
INSERT INTO `sys_dict` VALUES (2194, '应用名', 'overviewApp', '1', 'stun', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'STUN (Session Traversal Utilities for NAT) allows a client behind a NAT to establish UDP tunnels between two hosts');
INSERT INTO `sys_dict` VALUES (2195, '应用名', 'overviewApp', '1', 'sync', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Sync protocol is an RPC service allowing data synchronization');
INSERT INTO `sys_dict` VALUES (2196, '应用名', 'overviewApp', '1', 'syslog', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Syslog protocol is used for the transmission of event notification messages across networks between a client and a server');
INSERT INTO `sys_dict` VALUES (2197, '应用名', 'overviewApp', '1', 'tds', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'TDS protocol is used to communicate between SQL applications and a SQL Server');
INSERT INTO `sys_dict` VALUES (2198, '应用名', 'overviewApp', '1', 'telnet', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Telnet provides a fairly general bi-directional eight-bit byte oriented communications facility Its primary aim is to provide a standard method of interfacing between terminal devices and terminal-oriented processes');
INSERT INTO `sys_dict` VALUES (2199, '应用名', 'overviewApp', '1', 'telnets', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Secure version of the Telnet');
INSERT INTO `sys_dict` VALUES (2200, '应用名', 'overviewApp', '1', 'tftp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Trivial File Transfer Protocol (TFTP) is a file transfer protocol that is simpler to use than the File Transfer Protocol (FTP) but that proposes less features TFTP uses the User Datagram Protocol (UDP) rather than the Transmission Control Protocol (TCP)');
INSERT INTO `sys_dict` VALUES (2201, '应用名', 'overviewApp', '1', 'tibcordv', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'This protocol is used in the bank sector');
INSERT INTO `sys_dict` VALUES (2202, '应用名', 'overviewApp', '1', 'tns', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Transparent Network Service (TNS) is the Oracle (version 8 or higher) networking technology that provides a single application interface to all industry-standard networking protocols To connect to a database users initiate a connect request by passing information (username and password) along with a short name for the database service they wish to connect to');
INSERT INTO `sys_dict` VALUES (2203, '应用名', 'overviewApp', '1', 'tnvip', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Telnet VIP is an emulation of the Telnet protocol for VIP (Visual Information Projection) terminals');
INSERT INTO `sys_dict` VALUES (2204, '应用名', 'overviewApp', '1', 'ucp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Universal Computer Protocol is used by some mobile phones to send SMS');
INSERT INTO `sys_dict` VALUES (2205, '应用名', 'overviewApp', '1', 'vmware', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'VMWare is a solution vendor for virtualization This plugins provides generic classification for websites and cloud services under vmwarecom');
INSERT INTO `sys_dict` VALUES (2206, '应用名', 'overviewApp', '1', 'wikipedia', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Wikipedia is the biggest multilingual free-content encyclopedia on the Internet This plugin also classifies Wikimedia website traffic');
INSERT INTO `sys_dict` VALUES (2207, '应用名', 'overviewApp', '1', 'winmx', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'WinMX is a freeware peer-to-peer file sharing program authored by Frontcode Technologies that runs on Microsoft Windows operating systems and created in 2000');
INSERT INTO `sys_dict` VALUES (2208, '应用名', 'overviewApp', '1', 'wsp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Wireless Session Protocol (WSP) is an application layer protocol present in the WAP stack It is used by mobile stations to send SMS for example');
INSERT INTO `sys_dict` VALUES (2209, '应用名', 'overviewApp', '1', 'wtls', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Wireless Transport Layer Security (WTLS) is a security protocol part of the WAP stack It sits between the WTP and WDP layers in the WAP communications stack');
INSERT INTO `sys_dict` VALUES (2210, '应用名', 'overviewApp', '1', 'wtp', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Wireless Transaction Protocol (WTP) is a transport layer protocol which belongs to the WAP stack It provides a reliable transmission of network packets and is very similar to TCP');
INSERT INTO `sys_dict` VALUES (2211, '应用名', 'overviewApp', '1', 'x11', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'X11 is designed to communicate all the information necessary to operate a window system over a single asynchronous bi-directional stream of 8-bit bytes The X protocol specifies four types of messages but named extensions can also be defined to extend the system');
INSERT INTO `sys_dict` VALUES (2212, '应用名', 'overviewApp', '1', 'x25', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'X25 is a packet switched data network protocol which defines an international recommendation for the exchange of data as well as control information between a user device (host) called Data Terminal Equipment (DTE) and a network node called Data Circuit Terminating Equipment (DCE)');
INSERT INTO `sys_dict` VALUES (2213, '应用名', 'overviewApp', '1', 'xmlrpc', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'XMLRPC is a remote procedure calling using HTTP as the transport and XML as the encoding XML-RPC is designed to be as simple as possible while allowing complex data structures to be transmitted processed and returned');
INSERT INTO `sys_dict` VALUES (2214, '应用名', 'overviewApp', '1', 'xot', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Protocol used to transport x25 data over TCP in IP network');
INSERT INTO `sys_dict` VALUES (2215, '应用名', 'overviewApp', '1', 'yahoo_groups', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Yahoo! Groups offers free mailing lists photo and file sharing group calendars and more');
INSERT INTO `sys_dict` VALUES (2216, '应用名', 'overviewApp', '1', 'yahoo_search', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'This protocol is used to send queries to the Yahoo search engine');
INSERT INTO `sys_dict` VALUES (2217, '应用名', 'overviewApp', '1', 'ymail2', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'This protocol is the ajax based version of Webmail Yahoo');
INSERT INTO `sys_dict` VALUES (2218, '应用名', 'overviewApp', '1', 'youtube', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Youtube is a website where users can upload or watch videos');
INSERT INTO `sys_dict` VALUES (2219, '应用名', 'overviewApp', '1', 'yppasswd', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Yellow Page Password protocol enables the modification of logins and passwords in Network Interface System cards');
INSERT INTO `sys_dict` VALUES (2220, '应用名', 'overviewApp', '1', 'ypserv', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Yellow Pages Server is a protocol used to distribute NIS databases to client systems within an NIS domain');
INSERT INTO `sys_dict` VALUES (2221, '应用名', 'overviewApp', '1', 'ypupdate', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Yellow Pages Update protocol enables information updates in Network Information Services (NIS) cards');
