INSERT INTO `sys_dict` VALUES (2244, '应用名', 'overviewApp', '1', 'thunder', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Xunlei/Thunder is a Chinese multi-protocol download manager It uses several DDL websites and P2P protocols to retrieve files This plug-in only classifies Thunder-specific P2P protocols and miscellaneous HTTP/HTTPS traffic related to the Xunlei/Thunder application Downloads made by the application from public HTTP or FTP websites won\'t be classified as thunder but as http and ftp_data for most of them The usage of third party P2P protocols won\'t be classified as thunder but as bittorrent or edonkey instead');
