INSERT INTO `sys_dict` VALUES (3520, '应用名', 'overviewApp', '1', 'hotspot_shield', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'The Hotspot Shield application secures internet connections made from public access points using a VPN network');
INSERT INTO `sys_dict` VALUES (3521, '应用名', 'overviewApp', '1', 'allmusic', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Allmusic is an online music guide launched in 1991 as AMG (pre-dating the world wide web) This plug-in classifies navigation on the AllMusic web service and MP3 music playback Video clip streaming is handled by youtube');
INSERT INTO `sys_dict` VALUES (3522, '应用名', 'overviewApp', '1', 'mp3_rocket', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'MP3 Rocket is a music file downloader application It uses the Youtube (aka Google Video) service to search and download video clips and then transforms them into MP3 files on the host machine using a MP3 converter This plug-in only classifies secondary flows of the application like client updates Video clip downloads are classified as youtube');
INSERT INTO `sys_dict` VALUES (3523, '应用名', 'overviewApp', '1', 'hamachi', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Hamachi is a VPN service provided by LogMeIn This signature classifies traffic to the LogMeIn servers used by Hamachi The P2P VPN streams between users are using IPSEC and won\'t be classified as hamachi but ipsec instead');
INSERT INTO `sys_dict` VALUES (3524, '应用名', 'overviewApp', '1', 'peerguardian', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'PeerGuardian is capable of blocking incoming and outgoing connections based on IP blacklists This plug-in classifies the firewall attempts to update its blacklist from PeerGuardian servers');
