INSERT INTO `sys_dict` VALUES (5572, '供应商', 'overviewProvide', '1', 'Meituan', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Meituan operates as a web based shopping platform for locally found consumer products and retail services. The Company offers deals of the day by selling vouchers on local services and entertainment, dining, delivery, and other services. Meituan provides its services throughout China.');
INSERT INTO `sys_dict` VALUES (5573, '供应商', 'overviewProvide', '1', 'Bytedance', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'ByteDance Ltd. is a Chinese multinational internet technology company headquartered in Beijing and incorporated in the Cayman Islands.');
INSERT INTO `sys_dict` VALUES (5574, '供应商', 'overviewProvide', '1', 'Pinduoduo', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Pinduoduo Inc. is the largest Chinese agricultural-focused technology platform. It has created a platform that connects farmers and distributors with consumers directly through its interactive shopping experience.');
INSERT INTO `sys_dict` VALUES (5575, '供应商', 'overviewProvide', '1', 'Netease', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'NetEase, Inc. is a Chinese Internet technology company providing online services centered on content, community, communications, and commerce.');
INSERT INTO `sys_dict` VALUES (5576, '供应商', 'overviewProvide', '1', 'Kuaishou', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Kuaishou is a video-sharing mobile app that is developed by Beijing Kuaishou Technology Co., Ltd. It is popular with users outside China\'s Tier 1 cities.');
INSERT INTO `sys_dict` VALUES (5577, '供应商', 'overviewProvide', '1', '360cn', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Qihoo 360, full name Qihoo 360 Technology Co. Ltd., is a Chinese internet security company that has developed the antivirus software programs 360 Safeguard and 360 Mobile Safe, the Web browser 360 Secure Browser, and the mobile application store 360 Mobile Assistant.');
INSERT INTO `sys_dict` VALUES (5578, '供应商', 'overviewProvide', '1', 'Xiaomi', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Xiaomi Corporation, commonly known as Xiaomi and registered in Asia as Xiaomi Inc., is a Chinese designer and manufacturer of consumer electronics and related software, home appliances, and household items.');
INSERT INTO `sys_dict` VALUES (5579, '供应商', 'overviewProvide', '1', 'Sina', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Sina Corporation is a Chinese technology company. Sina operates four major business lines: Sina Weibo, Sina Mobile, Sina Online, and Sinanet. Sina has over 100 million registered users worldwide. ');
INSERT INTO `sys_dict` VALUES (5580, '供应商', 'overviewProvide', '1', 'Huawei', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Huawei Technologies Co., Ltd. is a Chinese multinational technology corporation headquartered in Shenzhen, Guangdong, China. It designs, develops, produces and sells telecommunications equipment, consumer electronics and various smart devices.');
INSERT INTO `sys_dict` VALUES (5581, '供应商', 'overviewProvide', '1', 'Beike', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'KE Holdings Inc is a China-based holding company engaged in housing transactions and related services.');
INSERT INTO `sys_dict` VALUES (5582, '供应商', 'overviewProvide', '1', 'Aiqiyi', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'iQIYI, Inc. is an innovative market-leading online entertainment service in China.');
INSERT INTO `sys_dict` VALUES (5583, '供应商', 'overviewProvide', '1', 'Ctrip', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Trip.com Group Limited is a Chinese multinational online travel company that provides services including accommodation reservation, transportation ticketing, packaged tours and corporate travel management.');
INSERT INTO `sys_dict` VALUES (5584, '供应商', 'overviewProvide', '1', 'Sohu', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Sohu, Inc. is a Chinese Internet company headquartered in the Sohu Internet Plaza in Haidian District, Beijing.[4][5] Sohu and its subsidiaries offer advertising, a search engine (Sogou.com), on-line multiplayer gaming (ChangYou.com) and other services.');
INSERT INTO `sys_dict` VALUES (5585, '供应商', 'overviewProvide', '1', 'YY', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'YY is a major Chinese video-based social network, a subsidiary of JOYY.');
INSERT INTO `sys_dict` VALUES (5586, '供应商', 'overviewProvide', '1', 'Xiaohongshu', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Xiaohongshu, also known as Little Red Book  is a social media and e-commerce platform. ');
INSERT INTO `sys_dict` VALUES (5587, '供应商', 'overviewProvide', '1', 'Apple', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Apple Inc. is an American multinational technology company that specializes in consumer electronics, software and online services headquartered in Cupertino, California, United States.');
INSERT INTO `sys_dict` VALUES (5588, '供应商', 'overviewProvide', '1', 'Microsoft', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Microsoft Corporation is an American multinational technology corporation which produces computer software, consumer electronics, personal computers, and related services headquartered at the Microsoft Redmond campus located in Redmond, Washington, United States.');
INSERT INTO `sys_dict` VALUES (5589, '供应商', 'overviewProvide', '1', 'Steam', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Steam parent company Valve has enjoyed enormous success as a game developer, thanks to titles like Half-Life, Counter-Strike: Global Offensive, and Dota 2.');
INSERT INTO `sys_dict` VALUES (5590, '供应商', 'overviewProvide', '1', 'Cibn', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'China International Radio and Television Network (CIBN for short) is a new media international communication platform established by China Radio International.');
INSERT INTO `sys_dict` VALUES (5591, '供应商', 'overviewProvide', '1', 'Amazon', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Amazon.com, Inc. is an American multinational technology company which focuses on e-commerce, cloud computing, digital streaming, and artificial intelligence.');
INSERT INTO `sys_dict` VALUES (5592, '供应商', 'overviewProvide', '1', 'Douyu', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'DouYu is a Chinese video live streaming service. ');
INSERT INTO `sys_dict` VALUES (5593, '供应商', 'overviewProvide', '1', 'Xunlei', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Xunlei Limited is a Chinese multinational technology company and an online service provider founded in 2003.');
INSERT INTO `sys_dict` VALUES (5594, '供应商', 'overviewProvide', '1', 'Cloudflare', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Cloudflare, Inc. is an American content delivery network and DDoS mitigation company, founded in 2010. ');
INSERT INTO `sys_dict` VALUES (5595, '供应商', 'overviewProvide', '1', 'Akamai', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Akamai Technologies, Inc. is an American content delivery network, a cybersecurity, and cloud service company, providing web and Internet security services. ');
INSERT INTO `sys_dict` VALUES (5596, '供应商', 'overviewProvide', '1', 'Ximalaya', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Ximalaya is a service website that enables users to share voices and personal radio stations.');
INSERT INTO `sys_dict` VALUES (5597, '供应商', 'overviewProvide', '1', 'Meitu', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Meitu Inc. is a Chinese technology company established in 2008 and headquartered in Xiamen, Fujian. It makes smartphones and selfie apps.');
INSERT INTO `sys_dict` VALUES (5598, '供应商', 'overviewProvide', '1', 'Zuoyebang', 'en', 0, 1, '2022-08-10 17:52:07', 1, 0, 'Zuoyebang is an online education startup that provides educational products and services to students in primary and high school.');
